// NCAAF win probability from the card's margin — fitted and validated in
// analysis/cfb_winprob_fit.py, which is the only reason this is allowed on a page.
//
// 🚨 HAND-WRITTEN ON PURPOSE, and it must stay in its own module. `web/app/ncaaf/model-data.ts`
// says "AUTO-GENERATED by cfb_export.py -- do not edit by hand" on its first line, and the nightly
// refresh rewrites it. Four helpers were once added to playerProjections.ts, the refresh wiped
// them, and every build failed. Import DATA and TYPES from the generated file; keep code here.
import { type NcaafCardGame } from "@/app/ncaaf/model-data";
import { normTeam } from "./cfbBoard";
import type { Game } from "./board";

/** SD of (our card margin − actual margin), fitted on the CHOOSE seasons only.
 *
 *  Measured by analysis/cfb_winprob_fit.py over 2021-25 FBS-vs-FBS games, with the margin built
 *  by production's own walk-forward path (cfb_card_backtest.run), never a re-derivation. Stable
 *  wherever the split is cut, which is why 16.0 is safe to hard-code:
 *
 *      split 2022   sd 15.98   held-out Brier 0.1884 vs 0.2448   +23.03%   fav won 71.2%
 *      split 2023   sd 16.12   held-out Brier 0.1875 vs 0.2442   +23.21%   fav won 71.1%
 *      split 2024   sd 16.01   held-out Brier 0.1866 vs 0.2446   +23.70%   fav won 71.6%
 *
 *  Calibration on the held-out seasons (the check a Brier score cannot do): mean predicted 58.8%
 *  against 57.6% realized, and every bucket within ~4 points. Notably it runs slightly UNDER on
 *  strong favourites — the 0.70-0.80 bucket predicts 74.6% and realizes 78.7% — so this number is
 *  conservative where it matters for a parlay rather than flattering. */
export const NCAAF_WIN_SD = 16.0;

/** Published beside the number, because a probability nobody can check is a decoration. */
export const NCAAF_WIN_SCORES = {
  brier: 0.1875, brierBase: 0.2442, gain: 23.2, favAcc: 71.1, n: 1022, sd: NCAAF_WIN_SD,
} as const;

const PHI = (z: number) => {
  // Abramowitz & Stegun 26.2.17 — plenty accurate for a displayed percentage, and avoids
  // pulling a stats dependency into the bundle for one function.
  const s = z < 0 ? -1 : 1, x = Math.abs(z) / Math.SQRT2;
  const t = 1 / (1 + 0.3275911 * x);
  const y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t
    + 0.254829592) * t * Math.exp(-x * x);
  return 0.5 * (1 + s * y);
};

/** FBS-vs-FBS only — the population the SD was validated on.
 *
 *  🚨 THIS GUARD IS THE WHOLE REASON THE NUMBER IS HONEST. cfb_card_backtest.load() selects
 *  `home_class='fbs' AND away_class='fbs'`, so every figure above describes FBS-vs-FBS games. The
 *  live card also carries cross-division games, which are blowouts: feeding a 40-point projected
 *  margin into Phi(m/16) returns ~99%, and since the parlay ranks by OUR confidence those games
 *  would take over the ticket — on a conversion never tested there, for games the books often do
 *  not even price.
 *
 *  USE THE CARD'S OWN FLAGS. cfb_export.build_card already emits `crossDiv` (the non-FBS side is
 *  rated from FCS results plus a fitted division offset) and `rated` (false when a side has no FBS
 *  rating history at all). Those are production's own classification, taken straight from
 *  `home_class`/`away_class` in cfb.db, so there is nothing to match and nothing to get wrong.
 *
 *  🚨 Three WRONG proxies were tried first, and the second one shipped an FCS team onto the live
 *  ticket before it was caught: `NCAAF_MODEL.top` is only the top 24, not the 136 teams rated;
 *  NCAAF_DEPTH's 138 teams are NOT the FBS universe (North Dakota State, an FCS program, is in
 *  it, and it duly appeared as a parlay leg); and the card's `conf` is populated on every game
 *  including cross-division ones, because it names the FBS side's conference. The flag was on the
 *  object the whole time. When a generated file seems not to carry what you need, read its
 *  generator's output dict before building a proxy out of names. */
export const isFbsVsFbs = (g: NcaafCardGame) => g.rated === true && g.crossDiv !== true;

/** Signed HOME margin from the card's `projSpread`, which names a favourite and a negative point. */
export function homeMargin(g: NcaafCardGame): number | null {
  const ps = g.projSpread;
  if (!ps || typeof ps.num !== "number") return null;
  return ps.fav === g.home ? -ps.num : ps.num;
}

/** P(home wins). null when the game is outside the validated population or has no projection. */
export function ncaafHomeWinProb(g: NcaafCardGame): number | null {
  if (!isFbsVsFbs(g)) return null;
  const m = homeMargin(g);
  return m === null ? null : PHI(m / NCAAF_WIN_SD);
}

/** Match a card game to its board game the way cfb_export/matchMarketLine does: normalised
 *  names plus a kickoff within 12 hours. Not the same ET day — CFBD stamps a TBD kickoff at
 *  23:59 ET, which lands on the other side of midnight from the feed. */
const KICK_TOL_MS = 12 * 3600 * 1000;
export function matchBoardGame(g: NcaafCardGame, board: Game[]): Game | null {
  const a = normTeam(g.away), h = normTeam(g.home);
  const t = g.commence ? Date.parse(g.commence) : NaN;
  const hits = board.filter((b) => {
    if (normTeam(b.home) !== h || normTeam(b.away) !== a) return false;
    return Number.isNaN(t) || Math.abs(Date.parse(b.commence) - t) <= KICK_TOL_MS;
  });
  if (hits.length) return hits[0];
  // Fall back to a containment match, as match_odds does: the feed spells out "Bowling Green
  // Falcons" where the card says "Bowling Green". Shortest match wins so "Miami" cannot swallow
  // "Miami (OH)".
  const loose = board
    .filter((b) => {
      const bh = normTeam(b.home), ba = normTeam(b.away);
      const ok = (bh.includes(h) || h.includes(bh)) && (ba.includes(a) || a.includes(ba));
      return ok && (Number.isNaN(t) || Math.abs(Date.parse(b.commence) - t) <= KICK_TOL_MS);
    })
    .sort((x, y) => (x.home.length + x.away.length) - (y.home.length + y.away.length));
  return loose[0] ?? null;
}
